<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';$user=require_role('supervisor');$errors=[];$success='';$editId=filter_var($_GET['editar']??null,FILTER_VALIDATE_INT)?:null;$form=['codigo'=>'','descripcion'=>'','ubicacion'=>''];
if($editId){$stmt=db()->prepare('SELECT id,codigo,descripcion,ubicacion FROM carros WHERE id=?');$stmt->execute([$editId]);$found=$stmt->fetch();if($found)$form=$found;else$editId=null;}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf_token']??null))$errors[]='La sesión expiró. Recarga la página.';$action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:null;if($action==='delete'&&$id){$check=db()->prepare('SELECT COUNT(*) FROM mantenciones WHERE carro_id=?');$check->execute([$id]);if((int)$check->fetchColumn()>0)$errors[]='No se puede eliminar un carro con mantenciones asociadas.';else{db()->prepare('DELETE FROM carros WHERE id=?')->execute([$id]);$success='Carro eliminado correctamente.';}}elseif($action==='save'){$form=['codigo'=>strtoupper(trim((string)($_POST['codigo']??''))),'descripcion'=>trim((string)($_POST['descripcion']??'')),'ubicacion'=>trim((string)($_POST['ubicacion']??''))];if(!preg_match('/^[A-Z0-9][A-Z0-9_-]{0,79}$/',$form['codigo']))$errors[]='El código debe usar letras, números, guion o guion bajo.';if(mb_strlen($form['descripcion'])>255||mb_strlen($form['ubicacion'])>120)$errors[]='La descripción o ubicación supera el límite permitido.';if(!$errors)try{if($id){$stmt=db()->prepare('UPDATE carros SET codigo=?,descripcion=?,ubicacion=? WHERE id=?');$stmt->execute([$form['codigo'],$form['descripcion']?:null,$form['ubicacion']?:null,$id]);$success='Carro actualizado correctamente.';}else{db()->prepare('INSERT INTO carros(codigo,descripcion,ubicacion) VALUES(?,?,?)')->execute([$form['codigo'],$form['descripcion']?:null,$form['ubicacion']?:null]);$success='Carro agregado correctamente.';}$form=['codigo'=>'','descripcion'=>'','ubicacion'=>''];$editId=null;}catch(PDOException $e){$errors[]=$e->errorInfo[1]===1062?'Ya existe un carro con ese código.':'No se pudo guardar el carro.';}}}
$carros=db()->query('SELECT c.id,c.codigo,c.descripcion,c.ubicacion,c.activo,COUNT(m.id) total_mantenciones FROM carros c LEFT JOIN mantenciones m ON m.carro_id=c.id GROUP BY c.id ORDER BY c.codigo')->fetchAll();require_once __DIR__.'/partials/layout.php';layout_start('Administrar carros',$user,'carros');
?><a class="module-back" href="panel.php">← Volver al escritorio</a><h1>Administrar carros</h1><p>Agrega, modifica y revisa los carros disponibles en el sistema.</p><?php if($errors): ?><div class="module-alert error"><ul><?php foreach($errors as $error): ?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><?php if($success): ?><div class="module-alert success"><?=e($success)?></div><?php endif;?><section class="module-card"><h2><?=$editId?'Editar carro':'Agregar carro'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)$editId)?>"><label for="codigo">Código</label><input id="codigo" name="codigo" maxlength="80" required value="<?=e($form['codigo'])?>"><label for="descripcion">Descripción</label><input id="descripcion" name="descripcion" maxlength="255" value="<?=e($form['descripcion'])?>"><label for="ubicacion">Ubicación</label><input id="ubicacion" name="ubicacion" maxlength="120" value="<?=e($form['ubicacion'])?>"><button type="submit"><?=$editId?'Guardar cambios':'Agregar carro'?></button></form></section><section class="module-card"><h2>Carros registrados</h2><table class="module-table"><thead><tr><th>Carro</th><th>Ubicación</th><th>Mantenciones</th><th>Acciones</th></tr></thead><tbody><?php foreach($carros as $carro): ?><tr><td data-label="Carro"><strong><?=e($carro['codigo'])?></strong><br><small><?=e($carro['descripcion']??'')?></small></td><td data-label="Ubicación"><?=e($carro['ubicacion']??'—')?></td><td data-label="Mantenciones"><?=e((string)$carro['total_mantenciones'])?></td><td data-label="Acciones"><div class="module-actions"><a href="carros.php?editar=<?=$carro['id']?>">Editar</a><?php if((int)$carro['total_mantenciones']===0): ?><form method="post" onsubmit="return confirm('¿Eliminar este carro definitivamente?');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$carro['id']?>"><button class="danger" type="submit">Eliminar</button></form><?php else: ?><span>Protegido por historial</span><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></section><?php layout_end();
